import{_ as t,o,c as s,a2 as p}from"./chunks/framework.Bg-Zxr5O.js";const f=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-en/Invoking-pspp_002dconvert.md","filePath":"manual-en/Invoking-pspp_002dconvert.md","lastUpdated":1785684581000}'),i={name:"manual-en/Invoking-pspp_002dconvert.md"};function a(n,e,r,c,d,l){return o(),s("div",null,[...e[0]||(e[0]=[p(`<h2 id="_18-invoking-pspp-convert" tabindex="-1">18 Invoking <code>pspp-convert</code> <a class="header-anchor" href="#_18-invoking-pspp-convert" aria-label="Permalink to &quot;18 Invoking \`pspp-convert\`&quot;">​</a></h2><p><code>pspp-convert</code> is a command-line utility accompanying PSPP. It reads an SPSS or SPSS/PC+ system file or SPSS portable file or encrypted SPSS syntax file input and writes a copy of it to another output in a different format. Synopsis:</p><pre><code>pspp-convert [options] input output

pspp-convert --help

pspp-convert --version
</code></pre><p>The format of input is automatically detected, when possible. The character encoding of old SPSS system files cannot always be guessed correctly, and SPSS/PC+ system files do not include any indication of their encoding. Use <code>-e encoding</code> to specify the encoding in this case.</p><p>By default, the intended format for output is inferred based on its extension:</p><p><code>csv</code><code>txt</code></p><p>Comma-separated value. Each value is formatted according to its variable’s print format. The first line in the file contains variable names.</p><p><code>sav</code><code>sys</code></p><p>SPSS system file.</p><p><code>por</code></p><p>SPSS portable file.</p><p><code>sps</code></p><p>SPSS syntax file. (Only encrypted syntax files may be converted to this format.)</p><p><code>pspp-convert</code> can convert most input formats to most output formats. Encrypted SPSS file formats are exceptions: if the input file is in an encrypted format, then the output file will be the same format (decrypted). To decrypt such a file, specify the encrypted file as input. The output will be the equivalent plaintext file. Options for the output format are ignored in this case.</p><p>The password for encrypted files can be specified a few different ways. If the password is known, use the -p option (documented below) or allow <code>pspp-convert</code> to prompt for it. If the password is unknown, use the -a and -l options to specify how to search for it, or --password-list to specify a file of passwords to try.</p><p>Use <code>-O format</code> to override the inferred format or to specify the format for unrecognized extensions.</p><p><code>pspp-convert</code> accepts the following general options:</p><p>-O format --output-format=format</p><p>Sets the output format, where format is one of the extensions listed above, <em>e.g.</em> : -O csv. Use --help to list the supported output formats.</p><p>-c maxcases --cases=maxcases</p><p>By default, all cases are copied from input to output. Specifying this option to limit the number of cases written to output to maxcases.</p><p>-e charset --encoding=charset</p><p>Overrides the encoding in which character strings in input are interpreted. This option is necessary because old SPSS system files, and SPSS/PC+ system files, do not self-identify their encoding.</p><p>-k variable… --keep=variable…</p><p>By default, <code>pspp-convert</code> includes all the variables from the input file. Use this option to list specific variables to include; any variables not listed will be dropped. The variables in the output file will also be reordered into the given order. The variable list may use <code>TO</code> in the same way as in PSPP syntax, <em>e.g.</em> if the dictionary contains consecutive variables <code>a</code>, <code>b</code>, <code>c</code>, and <code>d</code>, then --keep=&#39;a to d&#39; will include all of them (and no others).</p><p>-d variable… --drop=variable…</p><p>Drops the specified variables from the output.</p><p>When --keep and --drop are used together, --keep is processed first.</p><p>-h --help</p><p>Prints a usage message on stdout and exits.</p><p>-v --version</p><p>Prints version information on stdout and exits.</p><p>The following options affect CSV output:</p><p>--recode</p><p>By default, <code>pspp-convert</code> writes user-missing values to CSV output files as their regular values. With this option, <code>pspp-convert</code> recodes them to system-missing values (which are written as a single space).</p><p>--no-var-names</p><p>By default, <code>pspp-convert</code> writes the variable names as the first line of output. With this option, <code>pspp-convert</code> omits this line.</p><p>--labels</p><p>By default, <code>pspp-convert</code> writes variables’ values to CSV output files. With this option, <code>pspp-convert</code> writes value labels.</p><p>--print-formats</p><p>By default, <code>pspp-convert</code> writes numeric variables as plain numbers. This option makes <code>pspp-convert</code> honor variables’ print formats.</p><p>--decimal=decimal</p><p>This option sets the character used as a decimal point in output. The default is ‘.’.</p><p>--delimiter=delimiter</p><p>This option sets the character used to separate fields in output. The default is ‘,’, unless the decimal point is ‘,’, in which case ‘;’ is used.</p><p>--qualifier=qualifier</p><p>The option sets the character used to quote fields that contain the delimiter. The default is ‘&quot;’.</p><p>The following options specify how to obtain the password for encrypted files:</p><p>-p password --password=password</p><p>Specifies the password to use to decrypt an encrypted SPSS system file or syntax file. If this option is not specified, <code>pspp-convert</code> will prompt interactively for the password as necessary.</p><p>Be aware that command-line options, including passwords, may be visible to other users on multiuser systems.</p><p>When used with -a (or --password-alphabet) and -l (or --password-length), this option specifies the starting point for the search. This can be used to restart a search that was interrupted.</p><p>-a alphabet --password-alphabet=alphabet</p><p>Specifies the alphabet of symbols over which to search for an encrypted file’s password. alphabet may include individual characters and ranges delimited by ‘-’. For example, -a a-z searches lowercase letters, -a A-Z0-9 searches uppercase letters and digits, and -a &#39; -~&#39; searches all printable ASCII characters.</p><p>-l max-length --password-length=max-length</p><p>Specifies the maximum length of the passwords to try.</p><p>--password-list=file</p><p>Specifies a file to read containing a list of passwords to try, one per line. If file is -, reads from stdin.</p>`,58)])])}const u=t(i,[["render",a]]);export{f as __pageData,u as default};
